{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list):
        raise ValueError('segments must be list')
    for s in segments:
        for key in ('name','importance','minimum','capacity'):
            if key not in s:
                raise ValueError('missing ' + key)
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min:
        raise ValueError('budget below minimum sum')
    if budget > total_cap:
        raise ValueError('budget exceeds total capacity')
    n = len(segments)
    alloc = [s['minimum'] for s in segments]
    allocated = total_min
    while allocated < budget:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if alloc[i] < segments[i]['capacity']:
                score = segments[i]['importance'] / (alloc[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError('no eligible segment')
        alloc[best_idx] += 1
        allocated += 1
    allocations = alloc
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = budget
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"}
